// Build the LLM request. Kept in its own node so the prompt is
// readable and version-controlled rather than buried in a URL field.

const ticket = $input.first().json.body || $input.first().json;

const SYSTEM_PROMPT = [
  'You classify customer support tickets for a product team.',
  '',
  'Return ONLY a JSON object, no prose, no markdown fences:',
  '{',
  '  "theme": "no_status_visibility | timeline_not_met | no_response_from_support | money_not_received | amount_incorrect | other",',
  '  "severity": "low | medium | high",',
  '  "self_service_gap": true or false',
  '}',
  '',
  'self_service_gap is true when the customer contacted support only to obtain',
  'information the product should have displayed.',
  'If the complaint is about not being told, use no_status_visibility even when',
  'money is mentioned.'
].join('\n');

return [{
  json: {
    ticket_id: ticket.ticket_id || 'unknown',
    issue_type: ticket.issue_type || 'unknown',
    priority: ticket.priority || 'P3',
    customer_text: ticket.customer_text || '',
    llm_payload: {
      model: 'openai/gpt-oss-120b',
      temperature: 0,
      max_tokens: 800,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: ticket.customer_text || '' }
      ]
    }
  }
}];

// DETERMINISTIC BUSINESS RULES
//
// The LLM interprets language. It does NOT decide escalation.
// Escalation must be auditable and identical every time, so it lives here
// as explicit rules a human can read and a compliance team can sign off.

const upstream = $('Build LLM Request').first().json;
const response = $input.first().json;

// ---- parse the model output, tolerantly -------------------------------
let ai = null;
let aiError = null;

try {
  const raw = response.choices[0].message.content || '';
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  ai = JSON.parse(cleaned);
} catch (e) {
  aiError = 'unparseable_or_missing_response';
}

// ---- rules ------------------------------------------------------------
const HIGH_RISK_ISSUES = ['payment_failed', 'double_charge', 'delivery_lost'];

let action;
let reason;

if (ai === null) {
  // FAIL SAFE: if the AI is unavailable, a human handles it.
  // Never auto-respond on a guess.
  action = 'escalate';
  reason = 'ai_unavailable_fail_safe';

} else if (upstream.priority === 'P1' || HIGH_RISK_ISSUES.includes(upstream.issue_type)) {
  action = 'escalate';
  reason = 'high_risk_rule';

} else if (ai.theme === 'amount_incorrect') {
  action = 'escalate';
  reason = 'money_may_be_wrong';

} else if (ai.self_service_gap === true) {
  action = 'auto_respond';
  reason = 'information_request_only';

} else {
  action = 'escalate';
  reason = 'default_to_human';
}

// ---- structured log line ---------------------------------------------
return [{
  json: {
    ticket_id: upstream.ticket_id,
    issue_type: upstream.issue_type,
    priority: upstream.priority,
    ai_theme: ai ? ai.theme : null,
    ai_severity: ai ? ai.severity : null,
    ai_self_service_gap: ai ? ai.self_service_gap : null,
    ai_error: aiError,
    action: action,
    reason: reason,
    decided_at: new Date().toISOString()
  }
}];
